        hits = []
        ea = 0
        while True:
            res = ida_search.find_imm(ea, ida_search.SEARCH_DOWN, val)
            if isinstance(res, tuple):
                ea, _op = res
            else:
                ea = res
            if ea == 0xFFFFFFFFFFFFFFFF:
                break
            if ea <= 0 or ea > 0x10000000:
                break
            f = ida_funcs.get_func(ea)
            hits.append({"at": hex(ea), "func": ida_funcs.get_func_name(f.start_ea) if f else None})
            ea += 1
            if len(hits) >= limit:
                break
        return hits
